@php $math=\App\Services\CostingMath::class; @endphp
<section class="panel accounting-cost-result"><div class="section-heading"><h2>نتيجة الكلفة</h2><b class="badge {{ $result['stock_sufficient']?'good':'warn' }}">{{ $result['stock_sufficient']?'المواد تكفي وقت الحساب':'تحتاج شراء مواد قبل تسجيل الإنتاج' }}</b></div><div class="accounting-metrics"><article><span>كلفة الدفعة حسب المدخلات</span><strong dir="ltr">{{ $math::format($result['total_milli_iqd']) }} <small>د.ع</small></strong></article><article><span>كلفة الستيكر بهذه الدفعة</span><strong dir="ltr">{{ $math::format($result['unit_milli_iqd']) }} <small>د.ع</small></strong></article><article><span>الأوراق المصروفة</span><strong>{{ number_format($result['paper_sheets']) }}</strong></article><article><span>إنتاجك المعتمد لكل ورقة</span><strong>{{ number_format($result['parameters']['pieces_per_sheet']??0) }}</strong></article></div><div class="table-scroll"><table class="accounting-stock-table"><thead><tr><th>المادة</th><th>المطلوب</th><th>الرصيد وقت الحساب</th><th>متوسط كلفة الوحدة / د.ع</th><th>كلفة المادة / د.ع</th></tr></thead><tbody>@foreach($result['rows'] as $row)<tr><td>{{ $row['name'] }}</td><td>{{ $math::format($row['quantity_milli']) }} {{ \App\Models\StockItem::UNITS[$row['unit']] }}</td><td>{{ $math::format($row['available_milli']) }} @unless($row['sufficient'])<b class="badge warn">غير كافٍ</b>@endunless</td><td>{{ $math::format($row['unit_cost_milli_iqd']) }}</td><td>{{ $math::format($row['cost_milli_iqd']) }}</td></tr>@endforeach</tbody></table></div><div class="accounting-breakdown"><div class="summary-row"><span>مجموع المواد</span><b>{{ $math::format($result['materials_milli_iqd']) }} د.ع</b></div><div class="summary-row"><span>التكاليف الإضافية المدخلة</span><b>{{ $math::format($result['other_milli_iqd']) }} د.ع</b></div>@if($result['estimated_surplus_milli_iqd']!==null)<div class="summary-row total"><span>الفرق التقديري بين البيع والكلف المدخلة</span><b dir="ltr">{{ $math::format($result['estimated_surplus_milli_iqd']) }} د.ع</b></div>@endif</div><p class="tool-hint">ترتيب شبكي نظري حسب القياس والهوامش: {{ $result['theoretical_capacity'] }} قطعة بالورقة. يبقى عددك الفعلي هو المعتمد بالحساب.</p>@if($result['layout_review'])<p class="notice warning">عددك المدخل أعلى من الترتيب الشبكي النظري. راجع ترتيبك الفعلي قبل صرف المواد.</p>@endif<p class="tool-hint">الكلفة تشمل المكونات والأجور التي أدخلتها فقط. الهدر يقدّر على أوراق كاملة؛ المصروف الفعلي، إن أدخلته، يحل محله.</p></section>
